const [rawWidth, rawHeight] = format.split('x').map(Number);
const width = rawWidth || 1080;
const height = rawHeight || 1920;

// Clean script
const cleanScript = voiceoverScript
  .replace(/\s+/g, ' ')
  .trim();

// Truncate the entire script to fit in URL (max ~220 chars for safety)
// You can adjust this limit based on your needs
const maxScriptLength = 220;
let truncatedScript = cleanScript;

if (truncatedScript.length > maxScriptLength) {
  // Try to cut at a sentence boundary
  const cutIndex = truncatedScript.lastIndexOf('.', maxScriptLength);
  if (cutIndex > maxScriptLength * 0.5) {
    truncatedScript = truncatedScript.substring(0, cutIndex + 1);
  } else {
    truncatedScript = truncatedScript.substring(0, maxScriptLength);
  }
}

// Construct the full script as a single prompt
const prompt = `Pakistani young beautiful & bold lady explaining this: ${cleanScript} and in background should be corporate business office inside environment, 9:16 vertical, no text, no logo, no watermark.`;

// Create a single URL with the entire script
const url = `https://gen.pollinations.ai/video/${encodeURIComponent(
  prompt
)}?model=ltx-2&width=1080&height=1920&duration=10&aspectRatio=9%3A16&audio=true`;

// Return a single scene object
return [
  {
    json: {
      url,
      prompt,
      fullScript: cleanScript, // Store the full original script for reference
      truncatedScript,
      width,
      height,
      format
    }
  }
];

