const imageBase64 = response.data?.[0]?.b64_json || response.b64_json || response.imageBase64;

if (!imageUrl && !imageBase64) {
  throw new Error('OpenAI image response did not include url or b64_json. Full response: ' + JSON.stringify(response));
}

const imageFileName = `srlines-${source.feature || 'social'}-${Date.now()}.png`;
const imageDataUrl = imageBase64 ? `data:image/png;base64,${imageBase64}` : undefined;

const item = {
  json: {
    ...source,
    openAiResponse: response,
    imageUrl: imageUrl || imageDataUrl,
    imageBase64,
    imageDataUrl,
    imageMimeType: 'image/png',
    imageFileName,
  },
};

if (imageBase64) {
  item.binary = {
    data: {
      data: imageBase64,
      mimeType: 'image/png',
      fileName: imageFileName,
      fileExtension: 'png',
    },
  };
}

return [item];

// Get the imageDataUrl directly from Prepare Social Publishing Payload
const imageDataUrl = $('Prepare Social Publishing Payload').first().json.imageDataUrl;

if (!imageDataUrl) {
  throw new Error('No imageDataUrl found in Prepare Social Publishing Payload');
}

// Extract the base64 data from the data URL
// Format: data:image/png;base64,ABC123...
const base64Match = imageDataUrl.match(/^data:image\/\w+;base64,(.+)$/);

if (!base64Match) {
  throw new Error('Invalid data URL format. Expected: data:image/png;base64,...');
}

const imageBase64 = base64Match[1];

// Convert to binary
const buffer = Buffer.from(imageBase64, 'base64');
const binaryData = buffer.toString('base64');

// Create output with both JSON and binary
const result = {
  json: {
    ...$('Prepare Social Publishing Payload').first().json,
    imageBase64: imageBase64,
    imageSize: buffer.length,
    imageSizeKB: Math.round(buffer.length / 1024),
    extractedAt: new Date().toISOString()
  },
  binary: {
    data: {
      data: binaryData,
      mimeType: 'image/png',
      fileName: `srlines-image-${Date.now()}.png`,
      fileExtension: 'png'
    }
  }
};

return [result];
